package org.clafer.frontend;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.clafer.frontend.Syntax.*;

/**
 * Prints a syntax tree as the compiler's {@code printTree} prints its parse
 * tree ({@code PrintClafer}, generated by BNFC): the same words, parentheses
 * and line breaks. Two trees print the same text when they are the same tree,
 * up to the spans, so the text is what the parser is compared on with the
 * compiler's.
 * <p>
 * The output is not meant for reading: BNFC puts a line break after each
 * brace and semicolon, and the layout of the source is gone.
 */
public final class SyntaxPrinter {

    private final List<String> docs = new ArrayList<>();

    private SyntaxPrinter() {
    }

    /**
     * @param model a syntax tree
     * @return the text that {@code printTree} prints for the same tree
     */
    public static String print(Model model) {
        SyntaxPrinter printer = new SyntaxPrinter();
        for (Declaration d : model.declarations()) {
            printer.declaration(d);
        }
        return render(printer.docs);
    }

    private void doc(String s) {
        docs.add(s);
    }

    private void declaration(Declaration d) {
        switch (d) {
            case EnumDecl e -> {
                doc("enum");
                doc(e.name().text());
                doc("=");
                separated(e.literals(), "|");
            }
            case Element e -> element(e);
        }
    }

    private void separated(List<Ident> idents, String separator) {
        for (int i = 0; i < idents.size(); i++) {
            if (i > 0) {
                doc(separator);
            }
            doc(idents.get(i).text());
        }
    }

    private void element(Element e) {
        switch (e) {
            case Clafer c -> {
                if (c.isAbstract()) {
                    doc("abstract");
                }
                c.modifiers().forEach(m -> doc(m.kind().syntax()));
                c.groupCard().ifPresent(g -> {
                    switch (g) {
                        case GroupKeyword k -> doc(k.keyword());
                        case NCard n -> ncard(n);
                    }
                });
                doc(c.name().text());
                c.superClafer().ifPresent(s -> {
                    doc(":");
                    exp(26, s.exp());
                });
                c.reference().ifPresent(r -> {
                    doc(r.bag() ? "->>" : "->");
                    exp(23, r.exp());
                });
                card(c.card());
                c.init().ifPresent(i -> {
                    switch (i.how()) {
                        case Constant -> doc("=");
                        case Default -> doc(":=");
                        case Each -> {
                            doc(":=");
                            doc("each");
                        }
                        case Together -> {
                            doc(":=");
                            doc("together");
                        }
                    }
                    exp(0, i.exp());
                });
                c.transition().ifPresent(t -> {
                    arrow(t.arrow());
                    exp(0, t.exp());
                });
                elements(c.elements());
            }
            case ClaferUse u -> {
                doc("`");
                name(u.name());
                card(u.card());
                elements(u.elements());
            }
            case Constraint c -> {
                doc("[");
                exps(c.exps());
                doc("]");
            }
            case Assertion a -> {
                doc("assert");
                doc("[");
                exps(a.exps());
                doc("]");
            }
            case Goal g -> {
                doc("<<");
                doc(g.kind().syntax());
                exps(g.exps());
                doc(">>");
            }
        }
    }

    private void elements(Optional<Elements> elements) {
        elements.ifPresent(es -> {
            doc("{");
            es.elements().forEach(this::element);
            doc("}");
        });
    }

    private void card(Optional<Card> card) {
        card.ifPresent(c -> {
            switch (c) {
                case CardSymbol s -> doc(s.symbol());
                case CardNum n -> doc(n.number());
                case NCard n -> ncard(n);
            }
        });
    }

    private void ncard(NCard n) {
        doc(n.low());
        doc("..");
        doc(n.high().orElse("*"));
    }

    private void name(Name n) {
        separated(n.path(), "\\");
    }

    private void exps(List<Exp> exps) {
        exps.forEach(e -> exp(0, e));
    }

    private void arrow(TransArrow a) {
        if (a.guard().isPresent()) {
            doc("-[");
            exp(1, a.guard().get());
            doc(a.sync() ? "]->>" : "]->");
        } else {
            doc(a.sync() ? "-->>" : "-->");
        }
    }

    /**
     * {@code prt i e}: the expression, in parentheses if its level is below
     * {@code i} ({@code prPrec}).
     */
    private void exp(int i, Exp e) {
        boolean parens = e.level() < i;
        if (parens) {
            doc("(");
        }
        switch (e) {
            case TransitionExp t -> {
                exp(1, t.from());
                arrow(t.arrow());
                exp(0, t.to());
            }
            case Quantified q -> {
                doc(q.quant().syntax());
                if (q.disj()) {
                    doc("disj");
                }
                separated(q.decl().locals(), ";");
                doc(":");
                exp(21, q.decl().exp());
                doc("|");
                exp(1, q.body());
            }
            case IfThenElse ite -> {
                doc("if");
                exp(1, ite.condition());
                doc("then");
                exp(1, ite.then());
                doc("else");
                exp(1, ite.otherwise());
            }
            case Let l -> {
                doc("let");
                doc(l.local().text());
                doc("=");
                exp(16, l.value());
                doc("in");
                exp(1, l.body());
            }
            case Pattern p -> {
                switch (p.kind()) {
                    case Never, Sometime, LessOrOnce, Always -> {
                        doc(switch (p.kind()) {
                            case Never -> "never";
                            case Sometime -> "sometime";
                            case LessOrOnce -> "lonce";
                            default -> "always";
                        });
                        exp(3, p.exps().get(0));
                    }
                    case Precede, Follow -> {
                        exp(3, p.exps().get(0));
                        doc("must");
                        doc(p.kind() == PatternKind.Precede ? "precede" : "follow");
                        exp(3, p.exps().get(1));
                    }
                }
                p.scope().ifPresent(s -> {
                    switch (s.kind()) {
                        case Before -> doc("before");
                        case After, AfterUntil -> doc("after");
                        case BetweenAnd -> doc("between");
                    }
                    exp(11, s.exps().get(0));
                    if (s.kind() == ScopeKind.BetweenAnd || s.kind() == ScopeKind.AfterUntil) {
                        doc(s.kind() == ScopeKind.BetweenAnd ? "and" : "until");
                        exp(11, s.exps().get(1));
                    }
                });
            }
            case Anchor a -> {
                doc(a.initially() ? "initially" : "finally");
                exp(3, a.exp());
            }
            case Binary b -> {
                exp(b.op().level(), b.left());
                if (b.op() == BinaryOp.NotIn) {
                    doc("not");
                    doc("in");
                } else {
                    doc(b.op().syntax());
                }
                exp(b.op().level() + 1, b.right());
            }
            case Unary u -> {
                doc(u.op().syntax());
                exp(u.op().operandLevel(), u.exp());
            }
            case QuantExp q -> {
                doc(q.quant().syntax());
                exp(20, q.exp());
            }
            case ClaferId c -> name(c.name());
            case Literal l -> doc(l.text());
        }
        if (parens) {
            doc(")");
        }
    }

    // ------------------------------------------------------------------
    // BNFC's render
    // ------------------------------------------------------------------
    /**
     * BNFC's {@code render}, which composes functions on the rest of the
     * output: a line break drops the spaces that start the rest, and a word
     * is followed by a space unless it ends the output. The words are
     * grouped from the left, as {@code rend} matches them, then each group
     * is applied from the right.
     */
    static String render(List<String> docs) {
        record Step(int kind, String word, int indent) {
        }
        List<Step> steps = new ArrayList<>();
        int i = 0;
        int k = 0;
        while (k < docs.size()) {
            String t = docs.get(k);
            String next = k + 1 < docs.size() ? docs.get(k + 1) : null;
            switch (t) {
                case "[", "(" -> {
                    steps.add(new Step(0, t, i));
                    k++;
                }
                case "{" -> {
                    steps.add(new Step(1, t, i));
                    i++;
                    k++;
                }
                case "}" -> {
                    if (";".equals(next)) {
                        steps.add(new Step(2, t, i));
                        k += 2;
                    } else {
                        steps.add(new Step(3, t, i));
                        k++;
                    }
                    i--;
                }
                case ";" -> {
                    steps.add(new Step(4, t, i));
                    k++;
                }
                default -> {
                    if (",".equals(next)) {
                        steps.add(new Step(5, t, i));
                        k += 2;
                    } else if (")".equals(next) || "]".equals(next)) {
                        steps.add(new Step(6, t + next, i));
                        k += 2;
                    } else {
                        steps.add(new Step(7, t, i));
                        k++;
                    }
                }
            }
        }
        // the rest of the output, reversed, so that prepending is appending
        StringBuilder rest = new StringBuilder();
        for (int s = steps.size() - 1; s >= 0; s--) {
            Step step = steps.get(s);
            switch (step.kind()) {
                // "[" and "(": the character
                case 0 -> prepend(rest, step.word());
                // "{": the brace, a line break at the next indentation
                case 1 -> {
                    newLine(rest, step.indent() + 1);
                    prepend(rest, "{");
                }
                // "}" ";": a line break, "} ;", a line break
                case 2 -> {
                    newLine(rest, step.indent() - 1);
                    prepend(rest, ";");
                    space(rest, "}");
                    newLine(rest, step.indent() - 1);
                }
                // "}": a line break, the brace, a line break
                case 3 -> {
                    newLine(rest, step.indent() - 1);
                    prepend(rest, "}");
                    newLine(rest, step.indent() - 1);
                }
                // ";": the semicolon, a line break
                case 4 -> {
                    newLine(rest, step.indent());
                    prepend(rest, ";");
                }
                // t ",": t, then the comma and a space
                case 5 -> {
                    space(rest, ",");
                    prepend(rest, step.word());
                }
                // t ")" or t "]": t and the bracket, with no space
                case 6 -> prepend(rest, step.word());
                default -> space(rest, step.word());
            }
        }
        return rest.reverse().toString();
    }

    private static void prepend(StringBuilder reversed, String s) {
        for (int j = s.length() - 1; j >= 0; j--) {
            reversed.append(s.charAt(j));
        }
    }

    /**
     * {@code space t}: t, then a space unless the rest is empty.
     */
    private static void space(StringBuilder reversed, String t) {
        if (!reversed.isEmpty()) {
            reversed.append(' ');
        }
        prepend(reversed, t);
    }

    /**
     * {@code new i}: a line break and the indentation, with the spaces that
     * start the rest dropped.
     */
    private static void newLine(StringBuilder reversed, int indent) {
        int end = reversed.length();
        while (end > 0 && Character.isWhitespace(reversed.charAt(end - 1))) {
            end--;
        }
        reversed.setLength(end);
        reversed.append(" ".repeat(Math.max(0, 2 * indent)));
        reversed.append('\n');
    }
}
